import{_ as r,C as i,o as h,c as s,ah as o,E as c,j as d,a as e}from"./chunks/framework.DuX8SFU5.js";const A=JSON.parse('{"title":"AM_JOYSTICK — даташит","description":"","frontmatter":{"title":"AM_JOYSTICK — даташит","pdf":"/pdf/AM_JOYSTICK_datasheet.pdf","pdfStyle":"datasheet","pageClass":"datasheet-page","preliminary":true},"headers":[],"relativePath":"am_joystick/datasheet.md","filePath":"am_joystick/datasheet.md"}'),l={name:"am_joystick/datasheet.md"};function _(n,t,m,u,b,p){const a=i("AssetImage");return h(),s("div",null,[t[0]||(t[0]=o('<h2 id="_1-описание" tabindex="-1">1. Описание <a class="header-anchor" href="#_1-описание" aria-label="Permalink to &quot;1. Описание&quot;">​</a></h2><p>Узел переводит сигналы джойстика оператора в шину CAN, чтобы бортовой компьютер и другие узлы видели положение ручки и нажатые кнопки. Прошивка переводит ось в команду от −1 до +1, а кнопку или контакт — в 0 или 1; что делать с командой, решает получатель.</p><h2 id="_2-устроиство" tabindex="-1">2. Устройство <a class="header-anchor" href="#_2-устроиство" aria-label="Permalink to &quot;2. Устройство&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Узел</th><th>Что делает</th></tr></thead><tbody><tr><td>Модуль uNODE V2 (STM32F103)</td><td>DroneCAN, измерение питания, управление зуммером</td></tr><tr><td>TLA2528 IC1, I2C 0x10</td><td>8 аналоговых входов OUT1–OUT8</td></tr><tr><td>TLA2528 IC2, I2C 0x17</td><td>4 кнопки BT1–BT4 и 4 контакта 1SWA–4SWA</td></tr><tr><td>Зуммер MLT-8530</td><td>Короткий сигнал при включении</td></tr><tr><td>CAN1, CAN2</td><td>Два разъёма одной шины CAN с питанием</td></tr></tbody></table><p>Размер платы 50 × 50 мм, крепёжные отверстия по квадрату 34 мм.</p><h2 id="_3-входы" tabindex="-1">3. Входы <a class="header-anchor" href="#_3-входы" aria-label="Permalink to &quot;3. Входы&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Вход</th><th>Где</th><th>Тип</th><th>Команда</th><th><code>actuator_id</code> по умолчанию</th></tr></thead><tbody><tr><td>OUT1–OUT8</td><td>IC1, AIN0–AIN7</td><td>аналоговый</td><td>от −1 до +1</td><td>101–103 у OUT1–OUT3, OUT4–OUT8 выключены</td></tr><tr><td>1SWA–4SWA</td><td>IC2, AIN0–AIN3</td><td>цифровой</td><td>1 — контакт замкнут, 0 — разомкнут</td><td>111–114</td></tr><tr><td>BT1–BT4</td><td>IC2, AIN4–AIN7</td><td>цифровой</td><td>1 — кнопка нажата, 0 — отпущена</td><td>121–123 у BT1–BT3, BT4 выключена</td></tr><tr><td>VIN</td><td>MCU, PA0</td><td>аналоговый</td><td>напряжение питания, отдельным <code>CircuitStatus</code></td><td><code>cid</code> 17</td></tr></tbody></table><p>Аналоговые входы проходят делитель 10k/10k, АЦП TLA2528 12-битный с опорой 5 В; прошивка пересчитывает результат обратно в напряжение на разъёме. Напряжение <code>min_mv</code> даёт команду −1, <code>max_mv</code> — +1, между ними ось линейна, за пределами команда ограничена. Кнопки и контакты подтянуты к 5 В и замыкаются на землю. Опрос — 20 раз в секунду.</p><h3 id="_3-1-huiren-sj100" tabindex="-1">3.1. Huiren SJ100 <a class="header-anchor" href="#_3-1-huiren-sj100" aria-label="Permalink to &quot;3.1. Huiren SJ100&quot;">​</a></h3><p>Так входы платы связаны с органами джойстика SJ100; направления проверены на джойстике.</p><table tabindex="0"><thead><tr><th>Вход</th><th>Орган</th><th>Команда</th></tr></thead><tbody><tr><td>OUT1</td><td>ось X</td><td>+1 — вправо, −1 — влево</td></tr><tr><td>OUT2</td><td>ось Y</td><td>+1 — вперёд, −1 — назад</td></tr><tr><td>OUT3</td><td>ролик в рукоятке</td><td>+1 — вверх, −1 — вниз</td></tr><tr><td>1SWA, 2SWA</td><td>контакты оси X</td><td>1SWA — влево, 2SWA — вправо</td></tr><tr><td>3SWA, 4SWA</td><td>контакты оси Y</td><td>3SWA — вперёд, 4SWA — назад</td></tr><tr><td>BT1</td><td>клавиша сбоку рукоятки</td><td>1 — нажата</td></tr><tr><td>BT2, BT3</td><td>верхняя и нижняя красные кнопки</td><td>1 — нажата</td></tr></tbody></table><p>Контакты направления замыкаются, когда ручка выходит из нейтрали (по паспорту SJ100 — за ±3°). OUT4–OUT8 и BT4 у SJ100 не используются.</p><h2 id="_4-протокол" tabindex="-1">4. Протокол <a class="header-anchor" href="#_4-протокол" aria-label="Permalink to &quot;4. Протокол&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Протокол</td><td>DroneCAN</td></tr><tr><td>Имя узла</td><td><code>co.am.joystick.default</code></td></tr><tr><td>Входы</td><td><code>uavcan.equipment.actuator.ArrayCommand</code>, 20 раз в секунду, по записи на каждый включённый вход</td></tr><tr><td>Поле <code>command_type</code></td><td>0 (без единиц)</td></tr><tr><td>Питание</td><td><code>uavcan.equipment.power.CircuitStatus</code>, раз в секунду</td></tr></tbody></table><p>В одно сообщение помещается 15 входов; если включено больше, за тот же цикл уходит второе. Узел, который слушает <code>ArrayCommand</code> с тем же <code>actuator_id</code>, выполнит команду джойстика напрямую. Поэтому номера по умолчанию начинаются со 101: узлы нагрузок и клапанов по умолчанию используют 0–3. Если АЦП не отвечает, его входы пропадают из сообщения, узел сообщает о неисправности, а прошивка раз в секунду пытается подключить АЦП снова. Получатель должен считать вход потерянным, если команды по нему перестали приходить.</p><p>Если на одной шине несколько джойстиков, у каждой платы должны быть свои <code>uavcan.node.id</code>, <code>system.name</code> и <code>actuator_id</code>: иначе узлы конфликтуют, а входы двух джойстиков не различить. Удобно отдать джойстику сотню: левому 101–103, 111–114, 121–123, правому 201–203, 211–214, 221–223.</p><h2 id="_5-параметры" tabindex="-1">5. Параметры <a class="header-anchor" href="#_5-параметры" aria-label="Permalink to &quot;5. Параметры&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Параметр</th><th>По умолчанию</th><th>Назначение</th></tr></thead><tbody><tr><td><code>joystick.out1.aid</code> … <code>joystick.out8.aid</code></td><td>101, 102, 103, далее −1</td><td><code>actuator_id</code> оси; <code>-1</code> исключает её из сообщения</td></tr><tr><td><code>joystick.out1.min_mv</code> … <code>joystick.out8.min_mv</code></td><td>0</td><td>напряжение на разъёме для команды −1, мВ; больше <code>max_mv</code> — ось инвертирована</td></tr><tr><td><code>joystick.out1.max_mv</code> … <code>joystick.out8.max_mv</code></td><td>5000</td><td>напряжение на разъёме для команды +1, мВ</td></tr><tr><td><code>joystick.swa1.aid</code> … <code>joystick.swa4.aid</code></td><td>111–114</td><td><code>actuator_id</code> контакта 1SWA–4SWA; <code>-1</code> исключает его</td></tr><tr><td><code>joystick.bt1.aid</code> … <code>joystick.bt4.aid</code></td><td>121, 122, 123, −1</td><td><code>actuator_id</code> кнопки BT1–BT4; <code>-1</code> исключает её</td></tr><tr><td><code>joystick.vin.cid</code></td><td>17</td><td><code>cid</code> напряжения питания; <code>-1</code> отключает</td></tr><tr><td><code>joystick.axes_adc_address</code></td><td>16 (0x10)</td><td>адрес IC1 на I2C</td></tr><tr><td><code>joystick.buttons_adc_address</code></td><td>23 (0x17)</td><td>адрес IC2 на I2C</td></tr><tr><td><code>joystick.buzzer_hz</code></td><td>2700</td><td>частота зуммера, Гц</td></tr><tr><td><code>joystick.startup_beep_ms</code></td><td>150</td><td>длина сигнала при включении, мс; 0 — без сигнала</td></tr></tbody></table><p>С <code>min_mv</code> = 0 и <code>max_mv</code> = 5000 команда повторяет напряжение на разъёме (−1 — 0 В, 0 — 2,5 В, +1 — 5 В); так удобно снять реальные пределы и нейтраль оси перед настройкой.</p><h2 id="usb-check" tabindex="-1">6. Проверка с компьютера <a class="header-anchor" href="#usb-check" aria-label="Permalink to &quot;6. Проверка с компьютера {#usb-check}&quot;">​</a></h2><p>Джойстики проверяются без адаптера CAN и без ROS: плата <a href="./../am_node_v2/">AM_NODE_V2</a> с прошивкой <a href="./../am_node_v2/datasheet#usb-joystick">am_node_usb_joystick</a> на той же шине показывает оба джойстика компьютеру как один USB-джойстик.</p><ol><li>Настроить джойстики как левый и правый (<code>actuator_id</code> 1xx и 2xx, см. выше) и подключить их вместе с AM_NODE_V2 к одной шине CAN.</li><li>Подключить AM_NODE_V2 к компьютеру кабелем USB-C. Драйвер не нужен: в системе появится игровой контроллер <code>AM USB joystick</code>.</li><li>Открыть страницу проверки в Chrome или Edge. Установка и интернет не нужны.</li><li>Подвигать ручку или нажать кнопку: до первого действия браузер джойстик не показывает, и в заголовке написано «not found».</li></ol>',22)),c(a,{name:"am_joystick_dashboard.webp",alt:"Страница проверки: левая ручка вперёд и вправо, замкнуты контакты «вперёд» и «вправо», нажата боковая клавиша"}),t[1]||(t[1]=d("p",null,[e("Для каждого джойстика слева показана ручка сверху: точка — положение ручки, дуги вокруг — контакты направления, зелёная дуга — контакт замкнут. Справа — рукоятка: синяя метка на ролике, верхняя и нижняя красные кнопки, боковая клавиша; нажатая кнопка обведена зелёным, нажатая клавиша зелёная. Числа "),d("code",null,"x"),e(", "),d("code",null,"y"),e(", "),d("code",null,"r"),e(" — оси и ролик от −1 до +1, вперёд и вправо — плюс. Ниже — отчёт так, как его получает компьютер: 8 осей и 16 кнопок, номера кнопок — в "),d("a",{href:"./../am_node_v2/datasheet#usb-joystick-axes"},"таблице прошивки"),e(".")],-1)),c(a,{name:"am_joystick_dashboard_right.webp",alt:"Правый джойстик: ручка на себя, замкнут контакт «назад», ролик вверх, нажата верхняя красная кнопка",style:{width:"min(100%, 378px)"}}),t[2]||(t[2]=o('<p>Что проверить:</p><ul><li>Левая ручка двигает карточку «Left joystick», правая — «Right joystick». Если наоборот, у плат перепутаны <code>uavcan.node.id</code>, <code>system.name</code> и <code>actuator_id</code>.</li><li>В покое <code>x</code> и <code>y</code> около нуля и ни одна дуга не горит. Горящий контакт в покое значит, что ручка не возвращается в нейтраль.</li><li>Вправо — <code>x</code> к +1, вперёд — <code>y</code> к +1, ролик вверх — <code>r</code> к +1; дуга загорается уже на краю нейтрали.</li><li>Каждая кнопка и клавиша подсвечивается, пока нажата.</li></ul><p>Если джойстик пропал с шины, через 0,5 с его карточка встаёт в ноль со всеми кнопками отпущенными: в покое ручка обычно немного отклонена, поэтому ровные нули — признак потери связи. Кнопку, зажатую до открытия страницы, Chrome показывает отпущенной, пока её один раз не отпустят.</p><h2 id="_7-прошивка" tabindex="-1">7. Прошивка <a class="header-anchor" href="#_7-прошивка" aria-label="Permalink to &quot;7. Прошивка&quot;">​</a></h2><p>Прошивка собирается командой <code>make am_joystick_default</code> и загружается через загрузчик, как у остальных узлов: см. <a href="./../firmware_update">Обновление прошивки</a>.</p><h2 id="_8-известные-ограничения" tabindex="-1">8. Известные ограничения <a class="header-anchor" href="#_8-известные-ограничения" aria-label="Permalink to &quot;8. Известные ограничения&quot;">​</a></h2><ul><li>Фото платы для каталога пока нет.</li><li>Адреса АЦП и входы SJ100 проверены на плате, два джойстика работают на одной шине.</li><li>У осей нет мёртвой зоны и отдельной нейтрали: нейтраль — середина между <code>min_mv</code> и <code>max_mv</code>.</li><li>Зуммер пока подаёт только сигнал при включении.</li><li>Зуммер подключён к MCU через перемычку R25, которая в штатной сборке не устанавливается: без неё сигнала нет.</li></ul><h2 id="_9-история-документа" tabindex="-1">9. История документа <a class="header-anchor" href="#_9-история-документа" aria-label="Permalink to &quot;9. История документа&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Версия</th><th>Дата</th><th>Изменения</th></tr></thead><tbody><tr><td>0.1</td><td>2026-10-15</td><td>Технические сведения перенесены со страницы обзора в даташит</td></tr></tbody></table>',9))])}const T=r(l,[["render",_]]);export{A as __pageData,T as default};
